    return subprocess.check_output(["git","show",f"{rev}:{f}"],text=True)
def blocks(t):
    out=[]; cur=None
    for line in t.splitlines():
        if re.match(r'^\s*```',line):
            if cur is None: cur=[line]
            else: cur.append(line); out.append("\n".join(cur)); cur=None
        elif cur is not None: cur.append(line)
    return out
def fm(t):
    lines=t.splitlines()
    if lines and lines[0]=='---':
        end=lines.index('---',1)
        return "\n".join(lines[:end+1])
    return None
